mapper.select:
select c.C_Name as peCompanyName, c.C_Name_History as peCompanyNameHistory, unit.C_Name as peUnitName, pc.C_Name as pBuildUnitName, c.C_Abbreviation as peCompanyAbbName, unit.C_Abbreviation as peUnitAbbName, pc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompetentDepartmentName, case when mn.Pe_Contract_Category='02' then sr.Sc_Name else con.con_Name end as conName, case when mn.Pe_Contract_Category='02' then sr.Sc_Money else con.con_Money_Total end as conMoneyTotal, case when mn.Pe_Contract_Category='02' then sr.Sc_Type else con.con_Type end as conType, case when mn.Pe_Contract_Category='02' then sr.Sc_Code else con.con_Code end as conCode, pro.P_Name as pName, pro.P_Name_History as pNameHistory, u.U_Name as pePmName, f.file_relation_id as fileRelationId, sr.Sc_Title as scTitle, sr.Sc_Name as scName, sr.Sc_Code as scCode,
from Pe_Info mn left join Con_Contract con on mn.Pe_Con_Id=con.Con_Id left join Pre_Project pro on pro.P_Id=mn.Pe_Project_Id left join SYS_Company c on c.C_Id=mn.Pe_Company_Id left join SYS_Company unit on unit.C_Id=mn.Pe_Unit_Id left join SYS_Company pc on pc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_User u on mn.Pe_Pm_Uid=u.U_Id left join Subcontract_Record sr on mn.Pe_Sub_Contract=sr.Sc_Id left join Sys_File f on f.FileID=mn.Pe_Id
${params.authSql}
where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Pe_Create_Time desc

select c.C_Name as peCompanyName, unit.C_Name as peUnitName, pc.C_Name as pBuildUnitName, c.C_Abbreviation as peCompanyAbbName, unit.C_Abbreviation as peUnitAbbName, pc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompetentDepartmentName, case when mn.Pe_Contract_Category='02' then sr.Sc_Name else con.con_Name end as conName, case when mn.Pe_Contract_Category='02' then sr.Sc_Money else con.con_Money_Total end as conMoneyTotal, case when mn.Pe_Contract_Category='02' then sr.Sc_Type else con.con_Type end as conType, case when mn.Pe_Contract_Category='02' then sr.Sc_Code else con.con_Code end as conCode, pro.P_Name as pName, u.U_Name as pePmName, f.file_relation_id as fileRelationId, sr.Sc_Title as scTitle, sr.Sc_Name as scName, sr.Sc_Code as scCode,
from Pe_Info mn left join Con_Contract con on mn.Pe_Con_Id=con.Con_Id left join Pre_Project pro on pro.P_Id=mn.Pe_Project_Id left join SYS_Company c on c.C_Id=mn.Pe_Company_Id left join SYS_Company unit on unit.C_Id=mn.Pe_Unit_Id left join SYS_Company pc on pc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_User u on mn.Pe_Pm_Uid=u.U_Id left join Subcontract_Record sr on mn.Pe_Sub_Contract=sr.Sc_Id left join Sys_File f on f.FileID=mn.Pe_Id
1=1
and mn.Te_Id = #{params.teId}
and mn.Pe_Id in ( select Pe_id from Pe_Info_Collect left join Pe_Info_Collect_Dtl on Pe_Info_Collect.pec_Id=Pe_Info_Collect_Dtl.pec_Id
where Pe_Info_Collect.Pec_Flow_State = #{params.pecFlowState}
)
and mn.Pe_Id not in ( select Pe_Id from Pe_Meeting_Approval left join Pe_Meeting_Approval_List on Pe_Meeting_Approval.Ma_Id=Pe_Meeting_Approval_List.Ma_Id where Pe_Meeting_Approval.State !=3 and Pe_Id is not null )
order by mn.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select count(1) from Pe_Info mn left join Con_Contract con on mn.Pe_Con_Id=con.Con_Id left join Pre_Project pro on pro.P_Id=mn.Pe_Project_Id left join SYS_Company c on c.C_Id=mn.Pe_Company_Id left join SYS_Company unit on unit.C_Id=mn.Pe_Unit_Id left join SYS_Company pc on pc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_User u on mn.Pe_Pm_Uid=u.U_Id left join Subcontract_Record sr on mn.Pe_Sub_Contract=sr.Sc_Id left join Sys_File f on f.FileID=mn.Pe_Id
1=1
and mn.Te_Id = #{params.teId}
and mn.Pe_Id in ( select Pe_id from Pe_Info_Collect left join Pe_Info_Collect_Dtl on Pe_Info_Collect.pec_Id=Pe_Info_Collect_Dtl.pec_Id
where Pe_Info_Collect.Pec_Flow_State = #{params.pecFlowState}
)
and mn.Pe_Id not in ( select Pe_Id from Pe_Meeting_Approval left join Pe_Meeting_Approval_List on Pe_Meeting_Approval.Ma_Id=Pe_Meeting_Approval_List.Ma_Id where Pe_Meeting_Approval.State !=3 and Pe_Id is not null )

select
count(1)
from (
select t2.Con_Name,
t2.Con_Id,
t2.Con_Money_Total,
c1.C_Name as Construction_Unit,
c2.C_Name as Performing_Unit,
t1.Pe_Year,
t1.Pe_Quarter,
t1.Pe_Final_Score,
t1.Pe_Administrative_Sanction,
t1.Pe_Petition_Record from Pe_Info t1
left join Con_Contract t2 on t2.Con_Id=t1.Pe_Con_Id
left join SYS_Company c1 on t1.Pe_Unit_Id=c1.C_ID
left join SYS_Company c2 on t1.Pe_Company_Id=c2.C_ID
where t1.Pe_Type=#{params.peType}
and t1.Pe_Flow_State=#{params.state}
and Pe_Year=#{params.year}
and Pe_Quarter=#{params.peQuarter}

    and t1.Te_Id = #{params.teId}


    and t2.Con_Type in
    
        #{conType}
    

) t4
group by t4.Performing_Unit,t4.Pe_Year,t4.Pe_Quarter

select max(Construction_Unit) as constructionUnit, Performing_Unit as performingUnit, Pe_Year as peYear, Pe_Quarter as peQuarter, count(Con_Id) as conNumber, sum(Con_Money_Total) as conTotalPrice, wm_concat(Con_Name)as conName, sum(Pe_Final_Score)/ count(Con_Id) as averageScore, row_number() over (order by sum(Pe_Final_Score)/ count(Con_Id) desc) as ranking, sum(Pe_Administrative_Sanction) as peAdministrativeSanction, sum(Pe_Petition_Record) as pePetitionRecord from ( select t2.Con_Name, t2.Con_Id, t2.Con_Money_Total, c1.C_Name as Construction_Unit, c2.C_Name as Performing_Unit, t1.Pe_Year, t1.Pe_Quarter, t1.Pe_Final_Score, t1.Pe_Administrative_Sanction, t1.Pe_Petition_Record from Pe_Info t1 left join Con_Contract t2 on t2.Con_Id=t1.Pe_Con_Id left join SYS_Company c1 on t1.Pe_Unit_Id=c1.C_ID left join SYS_Company c2 on t1.Pe_Company_Id=c2.C_ID where t1.Pe_Type=#{params.peType} and t1.Pe_Flow_State=#{params.state} and Pe_Year=#{params.year} and Pe_Quarter=#{params.peQuarter}
and t1.Te_Id = #{params.teId}
and t2.Con_Type in
#{conType}
) t4 group by t4.Performing_Unit,t4.Pe_Year,t4.Pe_Quarter order by averageScore desc limit #{params.page},#{params.size}

select @rowNum:=@rowNum + 1 AS ranking,s.* from( select max(Construction_Unit) as constructionUnit, Performing_Unit as performingUnit, Pe_Year as peYear, Pe_Quarter as peQuarter, count(Con_Id) as conNumber, sum(Con_Money_Total) as conTotalPrice, GROUP_CONCAT(Con_Name)as conName, sum(Pe_Final_Score)/ count(Con_Id) as averageScore, sum(Pe_Final_Score) as scoreCount, count(Con_Id) as conIdCount, sum(Pe_Administrative_Sanction) as peAdministrativeSanction, sum(Pe_Petition_Record) as pePetitionRecord from ( select t2.Con_Name, t2.Con_Id, t2.Con_Money_Total, c1.C_Name as Construction_Unit, c2.C_Name as Performing_Unit, t1.Pe_Year, t1.Pe_Quarter, t1.Pe_Final_Score, t1.Pe_Administrative_Sanction, t1.Pe_Petition_Record from Pe_Info t1 left join Con_Contract t2 on t2.Con_Id=t1.Pe_Con_Id left join SYS_Company c1 on t1.Pe_Unit_Id=c1.C_ID left join SYS_Company c2 on t1.Pe_Company_Id=c2.C_ID where t1.Pe_Type=#{params.peType} and t1.Pe_Flow_State=#{params.state} and Pe_Year=#{params.year} and Pe_Quarter=#{params.peQuarter}
and t1.Te_Id = #{params.teId}
and t2.Con_Type in
#{conType}
) t4 group by t4.Performing_Unit,t4.Pe_Year,t4.Pe_Quarter order by averageScore desc ) s,(SELECT @rowNum:=0) b order by scoreCount/conIdCount desc

select max(Construction_Unit) as constructionUnit, Performing_Unit as performingUnit, Pe_Year as peYear, Pe_Quarter as peQuarter, count(Con_Id) as conNumber, sum(Con_Money_Total) as conTotalPrice, string_agg(Con_Name,',')as conName, sum(Pe_Final_Score)/ count(Con_Id) as averageScore, row_number() over (order by sum(Pe_Final_Score)/ count(Con_Id) desc) as ranking, sum(Pe_Administrative_Sanction) as peAdministrativeSanction, sum(Pe_Petition_Record) as pePetitionRecord from ( select t2.Con_Name, t2.Con_Id, t2.Con_Money_Total, c1.C_Name as Construction_Unit, c2.C_Name as Performing_Unit, t1.Pe_Year, t1.Pe_Quarter, t1.Pe_Final_Score, t1.Pe_Administrative_Sanction, t1.Pe_Petition_Record from Pe_Info t1 left join Con_Contract t2 on t2.Con_Id=t1.Pe_Con_Id left join SYS_Company c1 on t1.Pe_Unit_Id=c1.C_ID left join SYS_Company c2 on t1.Pe_Company_Id=c2.C_ID where t1.Pe_Type=#{params.peType} and t1.Pe_Flow_State=#{params.state} and Pe_Year=#{params.year} and Pe_Quarter=#{params.peQuarter}
and t1.Te_Id = #{params.teId}
and t2.Con_Type in
#{conType}
) t4 group by t4.Performing_Unit,t4.Pe_Year,t4.Pe_Quarter order by averageScore desc limit #{params.page},#{params.size}

select Pe_Competent_Department as dId,count(Pe_id) as num from Pe_Info where Pe_Flow_State=7

    and Pe_Year=#{yearStr}

group by Pe_Competent_Department having Pe_Competent_Department is not null

select conType,count(1) as num from ( select Pe_id as peId, case when mn.Pe_Contract_Category='02' then sr.Sc_Type else con.con_Type end as conType from Pe_Info mn left join Con_Contract con on mn.Pe_Con_Id=con.Con_Id left join Subcontract_Record sr on mn.Pe_Sub_Contract=sr.Sc_Id where Pe_Flow_State=7
and Pe_Year=#{yearStr}
)t1 group by conType
